<?php require 'config/database.php';$admin=password_hash('admin123',PASSWORD_DEFAULT);$student=password_hash('student123',PASSWORD_DEFAULT);$pdo->beginTransaction();try{$pdo->exec('DELETE FROM users');$pdo->prepare("INSERT INTO users(user_id,password,role,name) VALUES(?,?,?,?)")->execute(['ADMIN',$admin,'admin','Administrator']);$q=$pdo->query("SELECT id,name FROM students ORDER BY id")->fetchAll();$st=$pdo->prepare("INSERT INTO users(user_id,password,role,name,student_id) VALUES(?,?,?,?,?)");foreach($q as $i=>$s)$st->execute(['STU00'.($i+1),$student,'student',$s['name'],$s['id']]);if($pdo->query('SELECT COUNT(*) c FROM questions')->fetch()['c']==0){$q=$pdo->prepare('INSERT INTO questions(question,option_a,option_b,option_c,option_d,correct_answer) VALUES(?,?,?,?,?,?)');$q->execute(['Which language is used for styling web pages?','HTML','CSS','SQL','Python','B']);$q->execute(['Which SQL command retrieves data?','INSERT','UPDATE','SELECT','DELETE','C']);$q->execute(['What does DBMS stand for?','Database Management System','Data Basic Management Software','Digital Base Management System','None','A']);}$pdo->commit();echo '<h2>Setup complete.</h2><p>ADMIN / admin123 &nbsp; | &nbsp; STU001 / student123</p><b>Delete setup.php now.</b><br><a href="index.php">Open portal</a>';}catch(Exception $e){$pdo->rollBack;exit($e->getMessage());}?>
